function explain(state){const e=state.events.at(-1);const reasons={buy_filled:['Sanal alım gerçekleşti.','Örnek veri alım sinyali verdi. Bakiye ve risk kontrollerinden sonra komisyon ve kayma dahil edilerek pozisyon açıldı.'],buy_rejected:['Alım reddi örneği.','Bu olayda veri seti alım reddi üretiyor. Pozisyon açılmaz ve ücret yazılmaz.'],sell_rejected:['Satış reddi örneği.','Örnek veri satışın reddedildiğini bildiriyor. Pozisyon açık kalır; daha sonraki çıkış kontrolü devam eder.'],signal:['Satış sinyaliyle çıkış.','Örnek veride satış sinyali geldi. Açık pozisyon satılarak sanal bakiye güncellendi.'],stop:['Stop nedeniyle çıkış.','Gözlenen fiyat stop seviyesine veya altına düştü. Çıkış gözlenen fiyat, kayma ve ücretlerle hesaplandı.'],take_profit:['Kâr-al nedeniyle çıkış.','Gözlenen fiyat hedef seviyesine ulaştı. Pozisyon kapatıldı; komisyonlar sonuca dahil edildi.'],hold:['Pozisyon izleniyor.','Bu olayda yeni işlem gerçekleşmedi. Gözlenen fiyat portföy değerini güncelledi.'],buy_blocked_daily_limit:['Günlük sınır alımı engelledi.','Günlük kayıp sınırına ulaşıldığı için yeni alım yapılmadı. Açık pozisyonlar için çıkış kontrolleri devam eder.'],buy_blocked_position_limit:['Pozisyon sınırı alımı engelledi.','Açık pozisyon sayısı veya aynı paritedeki pozisyon yeni alıma izin vermedi.']};const r=e?(reasons[e.outcome]||['Olay değerlendirildi.','Örnek motorun bakiye ve risk kontrolleri uygulandı.']):['İlk adımı bekliyoruz.','Sonraki adımı oynat düğmesine basarak başlayın.'];el('why-title').textContent=r[0];el('why-text').textContent=r[1];}
function compare(){const a=scenarios[el('amount-a').value+'-'+el('stop-a').value],b=scenarios[el('amount-b').value+'-'+el('stop-b').value];el('comparison').replaceChildren();const rows=[['Son portföy',money(a.summary.equity),money(b.summary.equity)],['Net sonuç',money(a.summary.net_pnl),money(b.summary.net_pnl)],['Ücretler',money(a.summary.fees),money(b.summary.fees)],['Gerçekleşen sanal işlem',a.fills,b.fills]];for(const values of rows){const tr=document.createElement('tr');values.forEach(v=>cell(tr,String(v)));el('comparison').append(tr);}}
for(const id of ['amount-a','amount-b','stop-a','stop-b'])el(id).addEventListener('change',compare);compare();explain(states[cursor]);
